            }
            let hash = if path.ends_with("same-1.jpg") || path.ends_with("same-2.jpg") { "same" } else { path };
            Ok(ProbeInfo { format: "JPEG".into(), file_size: 4, content_hash: Some(hash.into()), ..Default::default() })
        });
        let input = ScanInput {
            probe: Some(probe),
            skip: None,
